async createTrialSignup(dto, metadata = {}, options = {}) {
        this.assertSelfServeTrialSignupEnabled();
        await this.rateLimitService.assertPreflight('trial_signup', {
            clientIp: metadata.clientIp,
            identity: dto.ownerEmail.trim().toLowerCase(),
        });
        if (options.expectedActivationId && !dto.trialActivationToken) {
            throw new common_1.BadRequestException({
                message: 'Trial activation token is required for this draft',
                error: { code: 'trial_activation_token_required' },
            });
        }
        let activationId = null;
        let createdTenantId = null;
        try {
            if (dto.trialActivationToken) {
                const activation = await this.trialActivationService.claim(dto.trialActivationToken, options.expectedActivationId);
                activationId = activation.id;
            }
            const temporaryPassword = dto.password?.trim() || this.generatePassword();
            const industryPresetId = dto.industryPresetId ?? industry_presets_1.DEFAULT_INDUSTRY_PRESET_ID;
            const calendarSource = dto.calendarSource ??
                (industryPresetId === 'solo_specialist'
                    ? domain_enums_1.CalendarSource.INTERNAL
                    : domain_enums_1.CalendarSource.EXTERNAL);
            const plan = dto.planId
                ? await this.subscriptionsService.getPlanByIdOrThrow(dto.planId)
                : await this.subscriptionsService.getPlanByNameOrThrow(calendarSource === domain_enums_1.CalendarSource.INTERNAL ? 'solo' : 'business');
            const trialFullAccess = Boolean(activationId);
            const trialEndsAt = this.addDays(new Date(), trial_activation_service_1.TRIAL_PERIOD_DAYS);
            const bookingMode = trialFullAccess && calendarSource === domain_enums_1.CalendarSource.INTERNAL
                ? 'live'
                : 'preview';
            const tenant = await this.tenantsService.createTenant({
                name: dto.name,
                slug: dto.slug,
                status: domain_enums_1.TenantStatus.TRIAL,
                planId: plan.id,
                industryPresetId,
                calendarSource,
                trialEndsAt: trialEndsAt.toISOString(),
                trialFullAccess,
                branchName: dto.branchName ?? dto.name,
                branchAddress: dto.branchAddress,
                branchPhone: dto.branchPhone,
                branchTimezone: dto.branchTimezone,
            });
            createdTenantId = tenant.id;
            const signup = await this.tenantContext.runAsSystemTenant(tenant.id, async () => {
                await this.brandingService.upsertBranding(tenant.id, {
                    appName: dto.name,
                    themeJson: {
                        industryPresetId,
                        calendarSource,
                        booking: {
                            mode: bookingMode,
                        },
                    },
                });
                if (calendarSource === domain_enums_1.CalendarSource.EXTERNAL) {
                    await this.crmService.ensureBootstrapMockIntegration(tenant.id, {
                        provider: domain_enums_1.CrmProvider.MOCK,
                        settingsJson: {
                            industryPresetId,
                        },
                    });
                }
                const user = await this.usersService.createUser({
                    tenantId: tenant.id,
                    email: dto.ownerEmail,
                    phone: (0, phone_util_1.normalizePhoneE164)(dto.ownerPhone),
                    name: dto.ownerName ?? null,
                    passwordHash: await bcrypt.hash(temporaryPassword, 10),
                    role: domain_enums_1.UserRole.TENANT_ADMIN,
                    status: domain_enums_1.UserStatus.ACTIVE,
                });
                if (calendarSource === domain_enums_1.CalendarSource.INTERNAL) {
                    await this.internalCalendarService.bootstrapEnsureProviderForUser(tenant.id, user.id, { displayName: dto.ownerName });
                }
                await this.auditLogService.log({
                    tenantId: tenant.id,
                    action: 'tenant.self_serve_created',
                    entityType: 'tenant',
                    entityId: tenant.id,
                    metadata: {
                        slug: tenant.slug,
                        trial_full_access: trialFullAccess,
                    },
                });
                await this.auditLogService.log({
                    tenantId: tenant.id,
                    userId: user.id,
                    action: 'tenant.self_serve_owner_created',
                    entityType: 'user',
                    entityId: user.id,
                    metadata: {
                        role: user.role,
                    },
                });
                return {
                    ...(await this.authService.issueSession(user, metadata)),
                    user: this.usersService.serializeUser(user),
                    tenant: {
                        id: tenant.id,
                        name: tenant.name,
                        slug: tenant.slug,
                        status: tenant.status,
                        allow_self_registration: tenant.allow_self_registration,
                        industry_preset_id: industryPresetId,
                        industry_preset: (0, industry_presets_1.getIndustryPreset)(industryPresetId),
                        calendar_source: calendarSource,
                        plan_id: plan.id,
                        trial_full_access: trialFullAccess,
                        trial_ends_at: trialEndsAt,
                    },
                    temporary_password: dto.password ? null : temporaryPassword,
                    booking_mode: bookingMode,
                    calendar_source: calendarSource,
                    trial: {
                        days: trial_activation_service_1.TRIAL_PERIOD_DAYS,
                        starts_at: new Date(trialEndsAt.getTime() - trial_activation_service_1.TRIAL_PERIOD_DAYS * 24 * 60 * 60 * 1000),
                        ends_at: trialEndsAt,
                        full_access: trialFullAccess,
                    },
                    next_step: calendarSource === domain_enums_1.CalendarSource.EXTERNAL
                        ? 'connect_crm'
                        : 'upload_logo_or_open_app',
                };
            });
            if (activationId) {
                await this.trialActivationService.complete(activationId, tenant.id);
            }
            return {
                ...signup,
                trial_activation: activationId
                    ? {
                        activation_id: activationId,
                        status: 'completed',
                        counted_as_connected_business: true,
                    }
                    : null,
            };
        }
        catch (error) {
            if (createdTenantId) {
                await this.tenantsService.deleteFailedTrialTenant(createdTenantId);
            }
            if (activationId) {
                await this.trialActivationService.release(activationId);
            }
            throw error;
        }
    }

assertSelfServeTrialSignupEnabled() {
        if (this.configService.get('SELF_SERVE_TRIAL_SIGNUP') === 'true') {
            return;
        }
        if (this.configService.get('NODE_ENV') !== 'production') {
            return;
        }
        throw new common_1.ForbiddenException({
            message: 'Регистрация новых салонов сейчас закрыта. Напишите нам — откроем доступ.',
            error: { code: 'self_serve_signup_disabled' },
        });
    }

async createTenant(dto) {
        this.assertHostNamesAllowed(dto);
        if (dto.currentPeriodStart !== undefined ||
            dto.currentPeriodEnd !== undefined ||
            dto.billingMethodId !== undefined ||
            dto.status === domain_enums_1.TenantStatus.ACTIVE ||
            dto.status === domain_enums_1.TenantStatus.PAST_DUE) {
            throw new common_1.BadRequestException('payment_derived_billing_fields_forbidden');
        }
        const existing = await this.prisma.tenant.findUnique({
            where: { slug: dto.slug.toLowerCase() },
            select: { id: true },
        });
        if (existing) {
            throw new common_1.ConflictException('Tenant slug already exists');
        }
        if (dto.planId) {
            await this.subscriptionsService.getPlanByIdOrThrow(dto.planId);
        }
        const billingDates = this.resolveBillingDates({
            status: dto.status ?? domain_enums_1.TenantStatus.TRIAL,
            trialEndsAt: normalizeOptionalDateString(dto.trialEndsAt),
        });
        const status = dto.status ?? domain_enums_1.TenantStatus.TRIAL;
        const tenant = await this.prisma.$transaction(async (tx) => {
            const normalizedBranchName = asNonEmptyString(dto.branchName) ?? dto.name;
            const normalizedBranchTimezone = asNonEmptyString(dto.branchTimezone);
            const created = await tx.tenant.create({
                data: {
                    name: dto.name,
                    slug: dto.slug.toLowerCase(),
                    status,
                    planId: dto.planId,
                    industryPresetId: dto.industryPresetId ?? industry_presets_1.DEFAULT_INDUSTRY_PRESET_ID,
                    calendarSource: dto.calendarSource ?? domain_enums_1.CalendarSource.EXTERNAL,
                    defaultCurrency: dto.defaultCurrency ?? 'RUB',
                    defaultTimezone: dto.defaultTimezone ??
                        normalizedBranchTimezone ??
                        salon_timezone_1.DEFAULT_SALON_TIMEZONE,
                    defaultLocale: dto.defaultLocale ?? 'ru-RU',
                    customDomain: dto.customDomain?.toLowerCase(),
                    subdomain: (dto.subdomain ?? dto.slug).toLowerCase(),
                    trialEndsAt: billingDates.trialEndsAt,
                    currentPeriodStart: null,
                    currentPeriodEnd: null,
                    pastDueAt: null,
                    graceEndsAt: null,
                    trialFullAccess: dto.trialFullAccess ?? false,
                    allowSelfRegistration: dto.allowSelfRegistration ?? true,
                },
            });
            await tx.brandingSettings.create({
                data: {
                    tenantId: created.id,
                    appName: dto.name,
                    themeJson: (0, json_util_1.asJson)({}),
                },
            });
            await tx.branch.create({
                data: {
                    tenantId: created.id,
                    name: normalizedBranchName,
                    address: asNonEmptyString(dto.branchAddress),
                    phone: asNonEmptyString(dto.branchPhone),
                    timezone: normalizedBranchTimezone,
                },
            });
            return created;
        });
        return this.serializeTenant(await this.getTenantByIdOrThrow(tenant.id));
    }

async deleteFailedTrialTenant(id) {
        return this.prisma.tenant.deleteMany({
            where: {
                id,
                status: domain_enums_1.TenantStatus.TRIAL,
                currentPeriodStart: null,
            },
        });
    }

createTenant(dto, actor) {
        return this.tenantsService.createTenant(dto).then(async (tenant) => {
            await this.tenantContext.runAsSystemTenant(tenant.id, () => this.auditLogService.log({
                tenantId: tenant.id,
                userId: actor.userId,
                action: 'tenant.created',
                entityType: 'tenant',
                entityId: tenant.id,
                metadata: {
                    slug: tenant.slug,
                },
            }));
            return tenant;
        });
    }
